// 智能选择素材和产品
const materialData = $('查询素材库').first().json;
const productData = $('查询产品库').first().json;

const materials = materialData.results || [];
const products = productData.results || [];

if (materials.length === 0) throw new Error('素材库为空');
if (products.length === 0) throw new Error('产品库为空');

// 随机选择1条素材
const material = materials[Math.floor(Math.random() * materials.length)];

// 提取素材信息
const materialInfo = {
  id: material.id,
  title: material.properties['标题']?.title?.[0]?.text?.content || '无标题',
  summary: material.properties['原文摘要']?.rich_text?.[0]?.text?.content || '',
  content: material.properties['详细内容']?.rich_text?.[0]?.text?.content || '',
  angles: material.properties['创作角度']?.rich_text?.[0]?.text?.content || '',
  keywords: material.properties['SEO关键词']?.multi_select?.map(k => k.name) || [],
  tags: material.properties['话题分类']?.multi_select?.map(t => t.name) || [],
  relatedTags: material.properties['关联产品']?.multi_select?.map(t => t.name) || []
};

// 基于素材标签匹配产品
let matchedProducts = products.filter(p => {
  const productTags = p.properties['产品标签']?.multi_select?.map(t => t.name) || [];
  return materialInfo.relatedTags.some(tag => productTags.includes(tag));
});

// 如果没有匹配，随机选择
if (matchedProducts.length === 0) {
  matchedProducts = products;
}

// 选择1-2款产品
const productCount = Math.random() > 0.5 ? 2 : 1;
const selectedProducts = [];
const usedIndices = new Set();

while (selectedProducts.length < productCount && selectedProducts.length < matchedProducts.length) {
  const index = Math.floor(Math.random() * matchedProducts.length);
  if (!usedIndices.has(index)) {
    usedIndices.add(index);
    const p = matchedProducts[index];
    selectedProducts.push({
      id: p.id,
      name: p.properties['产品名称']?.title?.[0]?.text?.content || '未命名',
      tags: p.properties['产品标签']?.multi_select?.map(t => t.name) || [],
      sellPoints: p.properties['核心卖点']?.rich_text?.[0]?.text?.content || '',
      description: p.properties['产品描述']?.rich_text?.[0]?.text?.content || '',
      scene: p.properties['使用场景']?.rich_text?.[0]?.text?.content || '',
      strategy: p.properties['植入策略']?.rich_text?.[0]?.text?.content || ''
    });
  }
}

// 读取平台配置
const platforms = (process.env.CONTENT_PLATFORMS || '小红书,微信公众号').split(',');

return [{
  json: {
    material: materialInfo,
    products: selectedProducts,
    platforms: platforms.map(p => p.trim()),
    timestamp: new Date().toISOString()
  }
}];

// 为每个平台创建任务
const data = $input.first().json;
const items = [];

for (const platform of data.platforms) {
  items.push({
    json: {
      ...data,
      platform: platform
    }
  });
}

return items;

