// 整合生成的内容
const taskData = $('拆分平台任务').item.json;
const titleResponse = $('AI生成标题').item.json;
const contentResponse = $input.first().json;

// 解析标题
let title = taskData.material.title;
try {
  const titleData = titleResponse.choices?.[0]?.message?.content || '{}';
  const match = titleData.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    title = parsed.title || title;
  }
} catch (e) {}

// 解析正文
let content = '';
let tags = [];
let images = [];
try {
  const contentData = contentResponse.choices?.[0]?.message?.content || '{}';
  const match = contentData.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    content = parsed.content || '';
    tags = parsed.tags || [];
    images = parsed.images || [];
  }
} catch (e) {
  content = '内容生成失败，请手动编辑';
}

const contentId = 'C' + Date.now() + Math.random().toString(36).substr(2, 5).toUpperCase();

return [{
  json: {
    contentId: contentId,
    title: title,
    platform: taskData.platform,
    contentType: taskData.platform === '小红书' ? '图文' : '深度文章',
    content: content,
    tags: tags,
    images: images,
    materialId: taskData.material.id,
    materialTitle: taskData.material.title,
    productIds: taskData.products.map(p => p.id),
    productNames: taskData.products.map(p => p.name).join('、'),
    generateMethod: 'AI生成',
    aiModel: process.env.AI_MODEL || 'gpt-4o-mini',
    strategy: '教育式',
    wordCount: content.length,
    status: '待审核',
    createdAt: new Date().toISOString()
  }
}];

// 构建Notion请求体
const d = $json;
const body = {
  parent: { database_id: process.env.NOTION_CONTENT_DB_ID },
  properties: {
    '标题': { title: [{ text: { content: d.title.substring(0, 100) } }] },
    '内容ID': { rich_text: [{ text: { content: d.contentId } }] },
    '平台': { select: { name: d.platform } },
    '内容类型': { select: { name: d.contentType } },
    '正文': { rich_text: [{ text: { content: d.content.substring(0, 2000) } }] },
    '话题标签': { multi_select: d.tags.slice(0, 10).map(t => ({ name: t })) },
    '配图列表': { rich_text: [{ text: { content: d.images.join('\n').substring(0, 500) } }] },
    '生成方式': { select: { name: d.generateMethod } },
    'AI模型': { select: { name: d.aiModel } },
    '内容策略': { select: { name: d.strategy } },
    '字数': { number: d.wordCount },
    '状态': { select: { name: d.status } },
    '创建时间': { date: { start: d.createdAt } }
  }
};
return [{ json: { notionBody: JSON.stringify(body), originalData: d } }];

// 生成执行摘要
const items = $input.first().json.data || [];
const successCount = items.filter(item => item.id).length;

const summary = `内容创作报告
==================
执行时间: ${new Date().toLocaleString('zh-CN')}

【创作结果】
- 成功: ${successCount}篇
- 失败: ${items.length - successCount}篇

【内容列表】
${items.slice(0, 5).map((item, i) => {
  const d = item.originalData;
  return `${i+1}. [${d?.platform}] ${d?.title} (${d?.wordCount}字)`;
}).join('\n')}

【下一步】
1. 在Notion内容库中审核内容
2. 修改优化后标记为

3. 使用发布工作流发布到平台`;

return [{
  json: {
    report: summary,
    successCount,
    totalCount: items.length,
    timestamp: new Date().toISOString()
  }
}];
